import { useState, type KeyboardEvent, type ReactNode } from "react"
import { useIsMobile } from "@/shared/lib/use-mobile"
import { cn } from "@/shared/lib/utils"
import { Button } from "@/shared/ui/button"
import { ConfirmDialog } from "@/shared/ui/confirm-dialog"
import { Dialog, DialogClose, DialogContent, DialogTitle } from "@/shared/ui/dialog"
import { MaximizeIcon, XIcon } from "@/shared/ui/icon"
import { Page, type Crumb } from "@/shared/ui/page"
import { Spinner } from "@/shared/ui/spinner"
import { Switch } from "@/shared/ui/switch"

export type ComposeSubmit = { label: string; onSubmit: () => void; isDisabled?: boolean; isPending?: boolean }

type ComposeSurfaceProps = {
  /** dialog: 목록 위 대화상자(데스크톱에서 목록의 버튼으로 열 때). page: 자기 페이지(링크 · 새로고침 · 크게 보기). 휴대폰은 늘 페이지. */
  surface: "dialog" | "page"
  /** 페이지의 경로. 마지막 단계가 양식의 이름(새 업무)이다. */
  crumbs: Crumb[]
  /** 놓일 곳(프로젝트 칩). 대화상자는 머리에, 페이지는 양식 위에. */
  chip?: ReactNode
  /** 속성 알약. 데스크톱은 양식 아래, 휴대폰은 바닥 줄 바로 위에 고정한다. */
  pills?: ReactNode
  submit: ComposeSubmit
  /** 바닥 줄 앞쪽의 다른 동작(이전 · 임시 저장). 휴대폰은 취소 앞에 둔다. */
  actions?: ReactNode
  /** 만들 수 없는 까닭이나 실패. 바닥 줄에서 만들기 옆(휴대폰은 바닥 줄 위)에 두어 어느 자리에서든 같은 곳에서 읽힌다. */
  error?: string
  /** 계속 만들기: 만든 뒤 제목과 본문만 비우고 속성은 남겨 다음 것을 쓴다. */
  isContinuing?: boolean
  onContinuing?: (isContinuing: boolean) => void
  onClose: () => void
  /** 쓴 것이 있다. 그러면 닫기(닫기 단추 · Esc · 바깥 누르기 · 취소)가 먼저 버릴지 묻고, 버리기를 고르면 onClose를 부른다. */
  isDirty?: boolean
  /** 버릴지 묻는 말을 양식에 맞게. 기본은 "작성 중인 내용을 버릴까요?" · "지금 닫으면 쓴 내용이 사라집니다." · "버리기". */
  discard?: { title?: string; description?: string; label?: string }
  /** 크게 보기: 같은 양식을 자기 페이지로. 대화상자에만 있다. */
  onExpand?: () => void
  /** 제목과 본문(ComposeFields). */
  children: ReactNode
}

/**
 * 만들기 양식이 놓이는 곳(호호코워크 ComposeSurface). 데스크톱 대화상자는 화면 위 12%에서 가운데로 뜨고(최대 45rem)
 * 머리에 놓일 곳 칩 · 이름 · 크게 보기 · 닫기, 바닥에 계속 만들기 · 만들기. 데스크톱 페이지는 45rem 단에 같은 양식과
 * 취소. 휴대폰은 늘 전체 화면 페이지: 앱 바 ←, 스크롤하는 양식, 고정한 알약 줄, 취소 · 만들기 바닥 줄(만들기가 남은 폭을 채운다).
 * 바닥 줄의 앞쪽에는 다른 동작(actions), 그 뒤에 까닭(error)을 둔다. Ctrl/⌘+Enter가 만들기를 누른다.
 * 쓴 것이 있으면(isDirty) 닫기 전에 버릴지 묻는다(ConfirmDialog).
 */
export function ComposeSurface({ isDirty = false, discard, ...props }: ComposeSurfaceProps) {
  const isMobile = useIsMobile()
  const [isDiscarding, setDiscarding] = useState(false)
  const { submit, onClose } = props
  const press = (event: KeyboardEvent) => {
    if (event.key !== "Enter" || !(event.ctrlKey || event.metaKey) || event.nativeEvent.isComposing) return
    event.preventDefault()
    if (!submit.isDisabled && !submit.isPending) submit.onSubmit()
  }
  const surface = { ...props, onKeyDown: press, onClose: () => (isDirty ? setDiscarding(true) : onClose()) }
  return (
    <>
      {isMobile ? <PhoneCompose {...surface} /> : props.surface === "page" ? <PageCompose {...surface} /> : <DialogCompose {...surface} />}
      <ConfirmDialog open={isDiscarding} onOpenChange={setDiscarding}
        title={discard?.title ?? "작성 중인 내용을 버릴까요?"} description={discard?.description ?? "지금 닫으면 쓴 내용이 사라집니다."}
        action={{ label: discard?.label ?? "버리기", onAction: () => { setDiscarding(false); onClose() } }} />
    </>
  )
}

type SurfaceProps = Omit<ComposeSurfaceProps, "isDirty" | "discard"> & { onKeyDown: (event: KeyboardEvent) => void }

const titleOf = (crumbs: Crumb[]) => crumbs[crumbs.length - 1]?.label ?? "작성"

function SubmitButton({ submit, className }: { submit: ComposeSubmit; className?: string }) {
  return (
    <Button className={cn("rounded-full px-3", className)} disabled={submit.isDisabled || submit.isPending}
      aria-keyshortcuts="Control+Enter Meta+Enter" title="Ctrl + Enter" onClick={submit.onSubmit}>
      {submit.isPending && <Spinner data-icon="inline-start" />}
      {submit.label}
    </Button>
  )
}

function Continuing({ value = false, onChange }: { value?: boolean; onChange: (value: boolean) => void }) {
  return (
    <label className="flex items-center gap-2 text-sm">
      <Switch checked={value} onCheckedChange={onChange} />
      계속 만들기
    </label>
  )
}

/** 바닥 줄의 다른 동작. 앞쪽에 붙고 나머지를 끝으로 민다. */
function Actions({ children }: { children: ReactNode }) {
  return <div data-slot="compose-actions" className="mr-auto flex items-center gap-1">{children}</div>
}

/** 까닭 한두 줄. 다른 동작이 없으면 이것이 앞쪽에 붙는다. */
function ErrorText({ children, className }: { children: string; className?: string }) {
  return <p data-slot="compose-error" role="alert" className={cn("line-clamp-2 min-w-0 text-sm text-destructive", className)}>{children}</p>
}

/** 데스크톱 바닥 줄: 다른 동작 · 까닭 · 계속 만들기 · (페이지면) 취소 · 만들기. */
function Foot({ actions, error, submit, isContinuing, onContinuing, onCancel, className }: Pick<SurfaceProps, "actions" | "error" | "submit" | "isContinuing" | "onContinuing"> & {
  onCancel?: () => void; className?: string
}) {
  return (
    <div className={cn("flex flex-wrap items-center justify-end gap-3", className)}>
      {actions && <Actions>{actions}</Actions>}
      {error && <ErrorText className={cn("flex-1 text-right", !actions && "text-left")}>{error}</ErrorText>}
      {onContinuing && <Continuing value={isContinuing} onChange={onContinuing} />}
      {onCancel && <Button variant="ghost" onClick={onCancel}>취소</Button>}
      <SubmitButton submit={submit} />
    </div>
  )
}

/** 제목 · 본문의 크기를 정하는 묶음. 페이지(data-page)에서는 제목이 크고 본문 자리가 높다. */
function Paper({ isPage, children }: { isPage?: boolean; children: ReactNode }) {
  return <div data-slot="compose-paper" data-page={isPage || undefined} className="group/compose flex min-w-0 flex-col gap-3">{children}</div>
}

function Pills({ children, className }: { children: ReactNode; className?: string }) {
  return <div role="group" aria-label="속성" className={cn("flex flex-wrap items-center gap-1.5", className)}>{children}</div>
}

function DialogCompose({ crumbs, chip, pills, submit, actions, error, isContinuing, onContinuing, onClose, onExpand, onKeyDown, children }: SurfaceProps) {
  return (
    <Dialog open onOpenChange={isOpen => { if (!isOpen) onClose() }}>
      <DialogContent showCloseButton={false} onKeyDown={onKeyDown}
        className="top-[12dvh] max-h-[76dvh] translate-y-0 gap-6 overflow-y-auto px-10 pt-7 pb-6 sm:max-w-180">
        <div className="flex min-w-0 items-center gap-3">
          {chip}
          <DialogTitle className="min-w-0 flex-1 truncate text-xl leading-normal font-semibold">{titleOf(crumbs)}</DialogTitle>
          <div className="-mr-2 flex shrink-0 items-center gap-1">
            {onExpand && <Button variant="ghost" size="icon-sm" aria-label="크게 보기" title="크게 보기" onClick={onExpand}><MaximizeIcon /></Button>}
            <DialogClose render={<Button variant="ghost" size="icon-sm" aria-label="닫기" title="닫기" />}><XIcon /></DialogClose>
          </div>
        </div>
        <Paper>{children}{pills && <Pills className="pt-1">{pills}</Pills>}</Paper>
        <Foot actions={actions} error={error} submit={submit} isContinuing={isContinuing} onContinuing={onContinuing} className="pt-5" />
      </DialogContent>
    </Dialog>
  )
}

function PageCompose({ crumbs, chip, pills, submit, actions, error, isContinuing, onContinuing, onClose, onKeyDown, children }: SurfaceProps) {
  return (
    <Page crumbs={crumbs}>
      <div className="flex flex-1 justify-center bg-background px-4 py-8" onKeyDown={onKeyDown}>
        <div className="flex w-full max-w-180 flex-col gap-6">
          {chip && <div className="flex">{chip}</div>}
          <Paper isPage>{children}{pills && <Pills className="pt-1">{pills}</Pills>}</Paper>
          <Foot actions={actions} error={error} submit={submit} isContinuing={isContinuing} onContinuing={onContinuing} onCancel={onClose} />
        </div>
      </div>
    </Page>
  )
}

function PhoneCompose({ crumbs, chip, pills, submit, actions, error, isContinuing, onContinuing, onClose, onKeyDown, children }: SurfaceProps) {
  return (
    <Page crumbs={crumbs} isFullScreen>
      <div className="flex min-h-0 flex-1 flex-col bg-background" onKeyDown={onKeyDown}>
        <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto overscroll-contain px-4 py-5">
          {chip && <div className="flex">{chip}</div>}
          <Paper isPage>{children}</Paper>
        </div>
        {pills && <Pills className="shrink-0 px-4 py-2">{pills}</Pills>}
        <footer className="flex shrink-0 flex-col gap-2 border-t px-4 pt-2 pb-[calc(0.75rem+env(safe-area-inset-bottom))]">
          {error && <ErrorText>{error}</ErrorText>}
          {onContinuing && <Continuing value={isContinuing} onChange={onContinuing} />}
          <div className="flex items-center gap-2">
            {actions && <div data-slot="compose-actions" className="flex shrink-0 items-center gap-1 [&_button]:h-11">{actions}</div>}
            <Button variant="ghost" className="h-11 min-w-22 px-4" onClick={onClose}>취소</Button>
            <SubmitButton submit={submit} className="h-11 min-w-22 flex-1" />
          </div>
        </footer>
      </div>
    </Page>
  )
}

/** 놓일 곳: 프로젝트 표식과 이름의 작은 알약. */
export function PlaceChip({ icon, label }: { icon: ReactNode; label: string }) {
  return (
    <span data-slot="place-chip" className="inline-flex h-6 max-w-48 shrink-0 items-center gap-1 rounded-full bg-muted px-2 text-xs font-medium [&_svg]:size-3.5 [&_svg]:shrink-0">
      {icon}<span className="truncate">{label}</span>
    </span>
  )
}

/**
 * 만들기 양식의 제목과 본문(호호코워크 ComposeForm): 테두리 없이 종이 위에 쓴다. 제목은 큰 글씨, 본문은 쓰는 만큼 늘어난다.
 * 크기는 놓인 곳(ComposeSurface)이 정한다: 대화상자는 18px 제목과 3.5rem 본문, 페이지는 24px 제목과 12rem 본문.
 */
export function ComposeFields({ title, onTitle, titlePlaceholder, body, onBody, bodyPlaceholder }: {
  title: string
  onTitle: (title: string) => void
  titlePlaceholder: string
  body: string
  onBody: (body: string) => void
  bodyPlaceholder: string
}) {
  return (
    <>
      <input aria-label="제목" placeholder={titlePlaceholder} autoFocus autoComplete="off" value={title} onChange={event => onTitle(event.target.value)}
        className="w-full bg-transparent text-lg leading-snug font-semibold outline-none placeholder:text-muted-foreground/70 group-data-page/compose:text-2xl" />
      <textarea aria-label="본문" placeholder={bodyPlaceholder} value={body} onChange={event => onBody(event.target.value)}
        className="field-sizing-content min-h-14 w-full resize-none bg-transparent leading-relaxed outline-none placeholder:text-muted-foreground/70 group-data-page/compose:min-h-48" />
    </>
  )
}

import { useId, useRef, useState, type DragEvent } from "react"
import { cn } from "@/shared/lib/utils"
import { UploadIcon } from "@/shared/ui/icon"
import { fileSizeText } from "./files"

/**
 * 받는 형식인지. accept는 input의 accept와 같은 꼴이다: 확장자(.png), 형식 묶음(image/*), 정확한 MIME(application/pdf).
 * 끌어다 놓은 파일은 브라우저가 accept로 거르지 않으므로 여기서 다시 본다.
 */
function isAccepted(file: File, accept: string | undefined, maxBytes: number | undefined) {
  if (file.size === 0 || (maxBytes !== undefined && file.size > maxBytes)) return false
  const formats = accept?.toLowerCase().split(",").map(format => format.trim()).filter(Boolean)
  if (!formats?.length) return true
  const name = file.name.toLowerCase()
  const type = file.type.toLowerCase()
  return formats.some(format => format.startsWith(".") ? name.endsWith(format)
    : format.endsWith("/*") ? type.startsWith(format.slice(0, -1)) : type === format)
}

/**
 * 파일을 끌어다 놓거나 눌러 고르는 자리(호호코워크 FileDropzone). 끌어 오는 동안 테두리가 진해지고 "여기에 놓으세요"가 된다.
 * 형식이나 크기가 맞지 않는 파일은 빼고 그 이름을 알린다. 하나만 받는 곳에 여럿을 놓으면 받지 않는다.
 * 무엇을 받는지(hint)가 없으면 크기 한도만 적는다. 고른 파일을 들고 있는 것은 부르는 쪽이다(onPick).
 */
export function FileDropzone({ label, hint, accept, maxBytes, isMultiple = false, isDisabled, onPick }: {
  /** 자리의 이름: "파일 추가", "사진 추가". */
  label: string
  /** 받는 형식과 크기의 안내: "JPG, PNG · 장당 최대 10 MB". */
  hint?: string
  accept?: string
  /** 파일 하나의 최대 크기(바이트). */
  maxBytes?: number
  isMultiple?: boolean
  isDisabled?: boolean
  onPick: (files: File[]) => void
}) {
  const input = useRef<HTMLInputElement>(null)
  const hintId = useId()
  const [isDragging, setDragging] = useState(false)
  const [problem, setProblem] = useState<string>()
  const about = hint ?? (maxBytes ? `파일당 최대 ${fileSizeText(maxBytes)}` : undefined)
  const choose = (files: File[]) => {
    if (isDisabled || files.length === 0) return
    if (!isMultiple && files.length > 1) return setProblem("파일은 한 번에 하나만 골라 주세요.")
    const valid = files.filter(file => isAccepted(file, accept, maxBytes))
    const invalid = files.filter(file => !valid.includes(file))
    setProblem(invalid.length > 0 ? `${invalid.map(file => file.name).join(", ")} 파일의 형식이나 크기를 확인해 주세요.` : undefined)
    if (valid.length > 0) onPick(valid)
  }
  const over = (event: DragEvent) => {
    if (!event.dataTransfer.types.includes("Files")) return
    event.preventDefault()
    event.dataTransfer.dropEffect = isDisabled ? "none" : "copy"
    if (!isDisabled) setDragging(true)
  }
  return (
    <div data-slot="file-dropzone" className="flex flex-col gap-2">
      <button type="button" aria-label={label} aria-describedby={about ? hintId : undefined} disabled={isDisabled} data-dragging={isDragging || undefined}
        onClick={() => input.current?.click()} onDragOver={over}
        onDragLeave={event => { if (!(event.relatedTarget instanceof Node) || !event.currentTarget.contains(event.relatedTarget)) setDragging(false) }}
        onDrop={event => { event.preventDefault(); setDragging(false); choose(Array.from(event.dataTransfer.files)) }}
        className={cn(
          "flex w-full flex-col items-center gap-1 rounded-lg border border-dashed border-input bg-muted/50 px-4 py-5 text-center outline-none",
          "hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:opacity-50",
          "data-dragging:border-ring data-dragging:bg-muted",
        )}>
        <UploadIcon className="size-5 text-muted-foreground" />
        <span className="text-sm font-medium">{label}</span>
        <span className="text-xs text-muted-foreground">{isDragging ? "여기에 놓으세요" : "파일을 끌어다 놓거나 눌러서 고르세요"}</span>
        {about && <span id={hintId} className="text-xs text-muted-foreground">{about}</span>}
      </button>
      <input ref={input} type="file" hidden aria-hidden tabIndex={-1} accept={accept} multiple={isMultiple} disabled={isDisabled}
        onChange={event => { choose(Array.from(event.currentTarget.files ?? [])); event.currentTarget.value = "" }} />
      {problem && <p role="alert" className="text-xs text-destructive">{problem}</p>}
    </div>
  )
}

import { useEffect, useState, type ReactNode } from "react"
import { Button } from "@/shared/ui/button"
import { FileIcon, ImageIcon, XIcon, type Icon } from "@/shared/ui/icon"
import { fileKey, fileSizeText } from "./files"

/** 사진의 작은 미리보기. 이 브라우저 안의 주소를 만들어 보이고, 사라질 때 놓는다. */
function PhotoPreview({ file }: { file: File }) {
  const [url, setUrl] = useState<string>()
  useEffect(() => {
    const preview = URL.createObjectURL(file)
    setUrl(preview)
    return () => URL.revokeObjectURL(preview)
  }, [file])
  return url ? <img src={url} alt="" className="size-8 shrink-0 rounded-md object-cover" /> : <ImageIcon className="size-8 shrink-0 p-1.5 text-muted-foreground" />
}

/** 줄 앞의 표식: 사진이면 미리보기, 아니면 형식의 표식(기본은 파일). */
export function FileMark({ file, icon: Mark = FileIcon }: { file?: File; icon?: Icon }) {
  if (file?.type.startsWith("image/")) return <PhotoPreview file={file} />
  return <Mark className="size-8 shrink-0 p-1.5 text-muted-foreground" />
}

/**
 * 고른 파일 목록의 한 줄: 표식 · 이름 · 설명(크기, "저장하면 빠집니다") · 끝의 동작(빼기, 되돌리기).
 * FileList가 고른 File을 이 줄로 그리고, 이미 붙어 있던 파일처럼 File이 아닌 것은 부르는 쪽이 이 줄로 더한다.
 */
export function FileRow({ media, name, description, action }: { media: ReactNode; name: string; description: ReactNode; action?: ReactNode }) {
  return (
    <li className="flex min-h-11 items-center gap-2.5 border-b py-1.5 last:border-b-0">
      {media}
      <span className="flex min-w-0 flex-1 flex-col">
        <span className="truncate text-sm">{name}</span>
        <span className="text-xs text-muted-foreground tabular-nums">{description}</span>
      </span>
      {action}
    </li>
  )
}

/** 줄 끝의 빼기. 휴대폰에서는 44px로 누른다. */
export function FileRemoveButton({ name, isDisabled, onClick }: { name: string; isDisabled?: boolean; onClick: () => void }) {
  return (
    <Button variant="ghost" size="icon-sm" aria-label={`${name} 빼기`} title="빼기" disabled={isDisabled} onClick={onClick} className="max-md:size-11">
      <XIcon />
    </Button>
  )
}

/**
 * 고른 파일 목록(호호코워크 compose의 파일 List): 줄마다 표식(사진이면 미리보기) · 이름 · 크기 · 빼기. 길면 안에서 스크롤한다.
 * children은 같은 목록 끝에 붙는 다른 줄(FileRow)이다. 고른 것도 더한 줄도 없으면 그리지 않는다.
 */
export function FileList({ label, files, icon, isDisabled, onRemove, children }: {
  /** 목록의 이름: "고른 회의 사진". */
  label: string
  files: File[]
  /** 사진이 아닌 파일의 표식. 기본은 파일. */
  icon?: Icon
  isDisabled?: boolean
  onRemove: (file: File) => void
  children?: ReactNode
}) {
  if (files.length === 0 && !children) return null
  return (
    <ul aria-label={label} className="flex max-h-[min(36dvh,17rem)] flex-col overflow-y-auto">
      {files.map(file => (
        <FileRow key={fileKey(file)} media={<FileMark file={file} icon={icon} />} name={file.name} description={fileSizeText(file.size)}
          action={<FileRemoveButton name={file.name} isDisabled={isDisabled} onClick={() => onRemove(file)} />} />
      ))}
      {children}
    </ul>
  )
}

export const MB = 1024 * 1024

/** 파일 크기의 글자: 1 MB부터 소수 한 자리 MB, 그 아래는 KB(0도 1 KB). */
export function fileSizeText(bytes: number) {
  if (bytes >= MB) return `${(bytes / MB).toFixed(1)} MB`
  return `${Math.max(1, Math.round(bytes / 1024))} KB`
}

/** 같은 파일인지 가리는 열쇠. 이름 · 크기 · 고친 때가 같으면 같은 파일로 본다. */
export const fileKey = (file: File) => `${file.name}:${file.size}:${file.lastModified}`

/** 고른 파일을 이미 든 것 뒤에 붙인다. 같은 파일을 두 번 고르면 하나만 남긴다. */
export function mergeFiles(current: File[], added: File[]) {
  const unique = new Map(current.map(file => [fileKey(file), file]))
  for (const file of added) if (!unique.has(fileKey(file))) unique.set(fileKey(file), file)
  return [...unique.values()]
}
